/* 对讲任务独占 HTTP 和 Cookie；不访问门禁连接。
 * C3 堆只够一次 TLS 握手：新建连接时非阻塞地占用操作锁，门禁忙就延后，握手完立即释放。 */
#include "tyg.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include "esp_crt_bundle.h"
#include "esp_http_client.h"
#include "esp_heap_caps.h"

#define TALK_RESPONSE_MAX 8192
#define TALK_REQUEST_HEAP_MIN 49152
#define TALK_REQUEST_BLOCK_MIN 24576
#define TALK_RESPONSE_HEAP_RESERVE 8192
static char endpoint[256];
static int endpoint_port = 6000;

void tg_talk_endpoint(const char *url, int port) {
    xSemaphoreTake(tg_state_lock, portMAX_DELAY);
    bool changed = strcmp(endpoint, url) || endpoint_port != port;
    tg_copy(endpoint, sizeof(endpoint), url); endpoint_port = port;
    xSemaphoreGive(tg_state_lock);
    if (changed) tg_sip_kick();
}

typedef struct { char cookie[256]; bool invalid; } talk_session;
/* 一次拉取的全部状态放在堆上，SIP 任务栈只留给 TLS。 */
typedef struct {
    esp_http_client_handle_t h;
    bool connected;
    talk_session session;
    char url[256], body[512], safe_code[64], seed[128], password[33];
    tg_talk_auth auth;
} talk_work;

static esp_err_t response_header(esp_http_client_event_t *event) {
    if (event->event_id != HTTP_EVENT_ON_HEADER || !event->header_key ||
        strcasecmp(event->header_key, "Set-Cookie")) return ESP_OK;
    talk_session *session = event->user_data;
    const char *value = event->header_value;
    if (!value) return ESP_OK;
    size_t n = strcspn(value, ";"), used = strlen(session->cookie);
    const char *equal = memchr(value, '=', n);
    if (!equal || equal == value ||
        memchr(value, '\r', n) || memchr(value, '\n', n)) {
        session->invalid = true; return ESP_OK;
    }
    /* 服务端通常只有 JSESSIONID；同名 Cookie 更新时替换原值。 */
    size_t name = (size_t)(equal - value);
    for (char *p = session->cookie; *p; ) {
        char *end = strstr(p, "; "); size_t len = end ? (size_t)(end - p) : strlen(p);
        if (len > name && !strncmp(p, value, name) && p[name] == '=') {
            size_t tail = end ? strlen(end) : 0;
            if (strlen(session->cookie) - len + n >= sizeof(session->cookie)) { session->invalid = true; return ESP_OK; }
            memmove(p + n, p + len, tail + 1); memcpy(p, value, n); return ESP_OK;
        }
        if (!end) break;
        p = end + 2;
    }
    if (n + used + (used ? 2 : 0) >= sizeof(session->cookie)) { session->invalid = true; return ESP_OK; }
    if (used) { memcpy(session->cookie + used, "; ", 2); used += 2; }
    memcpy(session->cookie + used, value, n); session->cookie[used + n] = 0;
    return ESP_OK;
}

static bool room_for_request(char *detail) {
    /* 只在新建 TLS 前检查；真机维持门禁连接时约有 61 KB 可用。 */
    size_t free_bytes = heap_caps_get_free_size(MALLOC_CAP_8BIT);
    size_t largest = heap_caps_get_largest_free_block(MALLOC_CAP_8BIT);
    if (free_bytes >= TALK_REQUEST_HEAP_MIN && largest >= TALK_REQUEST_BLOCK_MIN) return true;
    snprintf(detail, TG_DETAIL, "对讲内存不足（可用 %u KB，最大块 %u KB），稍后重试", (unsigned)(free_bytes / 1024), (unsigned)(largest / 1024));
    return false;
}
/* 打开失败时连接可能只建立了一半，也要关闭。 */
static void disconnect(talk_work *w) {
    esp_http_client_close(w->h);
    w->connected = false;
}
/* 四步请求复用同一条 TLS 连接；复用的连接已被关闭且请求未送出时重连一次。 */
static char *talk_http(talk_work *w, char *detail, int *retry_s) {
    size_t length = strlen(w->body);
    esp_err_t rc = ESP_OK;
    int status = 0;
    char *out = NULL; size_t used = 0, cap = 512;
    for (int attempt = 0; attempt < 2; attempt++) {
        bool reused = w->connected;
        if (!reused && !room_for_request(detail)) { *retry_s = 60; return NULL; }
        if (!reused && !xSemaphoreTake(tg_action_lock, 0)) {
            tg_copy(detail, TG_DETAIL, "门禁请求进行中，稍后重试"); *retry_s = 15; return NULL;
        }
        if (*w->session.cookie) esp_http_client_set_header(w->h, "Cookie", w->session.cookie);
        rc = esp_http_client_open(w->h, length);
        if (!reused) xSemaphoreGive(tg_action_lock);
        if (rc == ESP_OK) w->connected = true;
        if (rc == ESP_OK && esp_http_client_write(w->h, w->body, length) != (int)length) rc = ESP_FAIL;
        if (rc == ESP_OK || !reused) break;
        disconnect(w);
    }
    if (rc == ESP_OK && esp_http_client_fetch_headers(w->h) < 0) rc = ESP_FAIL;
    status = esp_http_client_get_status_code(w->h);
    if (rc == ESP_OK && status == 200 && !w->session.invalid) {
        out = malloc(cap);
        if (!out) rc = ESP_ERR_NO_MEM;
        while (out && rc == ESP_OK) {
            if (used + 1 == cap) {
                if (esp_http_client_is_complete_data_received(w->h)) break;
                if (cap == TALK_RESPONSE_MAX || heap_caps_get_free_size(MALLOC_CAP_8BIT) < TALK_RESPONSE_HEAP_RESERVE + cap * 2) { rc = ESP_ERR_NO_MEM; break; }
                char *grown = realloc(out, cap * 2);
                if (!grown) { rc = ESP_ERR_NO_MEM; break; }
                out = grown; cap *= 2;
            }
            int n = esp_http_client_read(w->h, out + used, cap - used - 1);
            if (n <= 0) { if (!esp_http_client_is_complete_data_received(w->h)) rc = ESP_FAIL; break; }
            used += n;
        }
        if (out) out[used] = 0;
    } else if (rc == ESP_OK) rc = ESP_FAIL;
    int tls_error = 0, tls_flags = 0;
    if (rc != ESP_OK) esp_http_client_get_and_clear_last_tls_error(w->h, &tls_error, &tls_flags);
    if (rc != ESP_OK || !esp_http_client_is_persistent_connection(w->h)) disconnect(w);
    if (rc != ESP_OK) {
        free(out); out = NULL;
        if (w->session.invalid) tg_copy(detail, TG_DETAIL, "对讲会话 Cookie 无效");
        else if (status && status != 200) snprintf(detail, TG_DETAIL, "对讲平台 HTTP %d", status);
        else if (rc == ESP_ERR_NO_MEM) { tg_copy(detail, TG_DETAIL, "对讲内存不足或响应过大"); *retry_s = 60; }
        else if (tls_error) snprintf(detail, TG_DETAIL, "对讲网络请求失败（%s，TLS %d）", esp_err_to_name(rc), tls_error);
        else snprintf(detail, TG_DETAIL, "对讲网络请求失败（%s）", esp_err_to_name(rc));
    }
    return out;
}

static bool talk_step(talk_work *w, char *detail, int *retry_s) {
    char *reply = talk_http(w, detail, retry_s);
    if (!reply) return false;
    char fault[16];
    bool ok = tg_xml_text(reply, "faultCode", fault, sizeof(fault)) && !strcmp(fault, "0");
    if (!ok) {
        if (tg_code_valid(fault, false)) snprintf(detail, TG_DETAIL, "对讲平台拒绝（代码 %s）", fault);
        else tg_copy(detail, TG_DETAIL, "对讲平台未确认成功");
    }
    free(reply); return ok;
}

static bool fetch_steps(talk_work *w, int port, tg_sip_config *out, char *detail, const char **stage, int *retry_s) {
    snprintf(w->body, sizeof(w->body), "<message><msgType>AuthcodeRequest</msgType></message>");
    char *reply = talk_http(w, detail, retry_s);
    if (!reply) return false;
    bool got = tg_xml_text(reply, "safeCode", w->safe_code, sizeof(w->safe_code)) && *w->safe_code;
    free(reply);
    if (!got) { tg_copy(detail, TG_DETAIL, "平台未返回安全码"); return false; }
    if (!*w->session.cookie) { tg_copy(detail, TG_DETAIL, "平台未返回会话 Cookie"); return false; }
    *stage = "账号认证";
    snprintf(w->seed, sizeof(w->seed), "%s:%s", w->auth.password_md5, w->safe_code); tg_md5_hex(w->seed, w->password);
    snprintf(w->body, sizeof(w->body), "<message><msgType>AuthenticationRequest</msgType><userName>%s</userName><password>%s</password></message>",
             w->auth.account, w->password);
    if (!talk_step(w, detail, retry_s)) return false;
    *stage = "查询配置版本";
    snprintf(w->body, sizeof(w->body), "<message><msgType>ConfigInformRequest</msgType><configVersion>0</configVersion>"
             "<dedicatedNumber>%s</dedicatedNumber><serialNumber>%s</serialNumber></message>", w->auth.account, w->auth.account);
    if (!talk_step(w, detail, retry_s)) return false;
    *stage = "下载 SIP 配置";
    snprintf(w->body, sizeof(w->body), "<message><msgType>MobileDownloadConfigRequest</msgType><dedicatedNumber>%s</dedicatedNumber></message>", w->auth.account);
    reply = talk_http(w, detail, retry_s);
    if (!reply) return false;
    bool ok = tg_talk_config(reply, port, out, detail);
    free(reply); return ok;
}

bool tg_talk_fetch(tg_sip_config *out, char *detail, int *retry_s) {
    memset(out, 0, sizeof(*out)); *retry_s = 300;
    talk_work *w = calloc(1, sizeof(*w));
    if (!w) { tg_copy(detail, TG_DETAIL, "对讲请求内存不足"); *retry_s = 60; return false; }
    int port;
    xSemaphoreTake(tg_state_lock, portMAX_DELAY);
    w->auth = tg_talk; tg_copy(w->url, sizeof(w->url), endpoint); port = endpoint_port;
    xSemaphoreGive(tg_state_lock);
    bool ok = false; const char *stage = NULL;
    /* 前置条件未满足时不带阶段前缀，并尽快重试（服务发现完成也会提前唤醒）。 */
    if (!*w->auth.account || !*w->auth.password_md5) tg_copy(detail, TG_DETAIL, "尚无对讲账号，请重新登录");
    else if (!tg_time_ready()) { tg_copy(detail, TG_DETAIL, "对讲等待网络校时"); *retry_s = 5; }
    else if (!tg_url_allowed(w->url, false, false)) { tg_copy(detail, TG_DETAIL, "等待对讲平台服务发现"); *retry_s = 30; }
    else {
        esp_http_client_config_t cfg = {.url = w->url, .timeout_ms = 8000, .crt_bundle_attach = esp_crt_bundle_attach,
            .disable_auto_redirect = true, .buffer_size = 512, .buffer_size_tx = 512, .keep_alive_enable = false,
            .event_handler = response_header, .user_data = &w->session};
        stage = "获取安全码";
        w->h = esp_http_client_init(&cfg);
        if (!w->h) { tg_copy(detail, TG_DETAIL, "对讲请求内存不足"); *retry_s = 60; }
        else {
            esp_http_client_set_method(w->h, HTTP_METHOD_POST);
            esp_http_client_set_header(w->h, "Content-Type", "text/xml; charset=utf-8");
            ok = fetch_steps(w, port, out, detail, &stage, retry_s);
            disconnect(w); esp_http_client_cleanup(w->h);
        }
        if (!ok) { char reason[TG_DETAIL]; tg_copy(reason, sizeof(reason), detail); snprintf(detail, TG_DETAIL, "%s失败：%.140s", stage, reason); }
    }
    memset(w, 0, sizeof(*w)); free(w);
    return ok;
}
